import { openSync,writeSync,fsyncSync,closeSync } from 'node:fs';
import { basename,dirname,join,resolve } from 'node:path';
import { z } from 'zod';
import { defineTool } from '@mayura/tools';
import { createSqliteStore } from '@mayura/storage';
import { createWorkflowTreeCoordinator,createWorkflowTreeRuntime,defineWorkflowTree } from '@mayura/workflows/children';

const [action,directory,existingRunId]=process.argv.slice(2);if(!['start','recover'].includes(action)||!directory)throw new Error('Invalid coordinator recovery fixture arguments.');const fixtureDirectory=resolve(directory);if(!basename(fixtureDirectory).startsWith('mayura-tree-coordinator-recovery-'))throw new Error('Unexpected fixture directory.');const filename=join(fixtureDirectory,'workflow-tree.sqlite');const effectFile=join(fixtureDirectory,'effects.ndjson');if(dirname(filename)!==fixtureDirectory||dirname(effectFile)!==fixtureDirectory)throw new Error('Fixture path escaped its directory.');
function notify(message){return new Promise((done,reject)=>{if(!process.send)return reject(new Error('IPC parent required.'));process.send(message,error=>error?reject(error):done());});}
function effect(context){const descriptor=openSync(effectFile,'a');try{writeSync(descriptor,`${JSON.stringify({runId:context.runId,callId:context.callId})}\n`);fsyncSync(descriptor);}finally{closeSync(descriptor);}}
const tool=defineTool({id:'fleet.write',version:'1',description:'Record one fleet effect.',input:z.number(),output:z.number(),effects:'write',capabilities:[],costMicros:1,execute:async(value,context)=>{effect(context);return value+1;}});const tree=defineWorkflowTree({id:'fleet-tree',version:'1',input:z.number(),output:z.number(),nodes:[{kind:'tool',id:'work',tool,input:{kind:'input',path:[]}}],result:{kind:'step',stepId:'work',path:[]}});const rawStore=createSqliteStore({filename});const shared={scope:{principalId:'fleet-process',projectId:'project'},permissions:{allow:['tool:fleet.write','effect:write']},policyVersion:'1',maxCostMicros:1,maxCalls:1,maxOutputBytes:1_024};let phase='initialize';
try{await rawStore.initialize();if(action==='start'){phase='submit';const submitter=createWorkflowTreeRuntime({store:rawStore,...shared,workerId:'submitter'});const submitted=await submitter.submit(tree,{input:1,idempotencyKey:'fleet-process'});await submitter.close();const wrapped={...rawStore,workflowTrees:{...rawStore.workflowTrees,inspect:async command=>{await notify({kind:'observed',runId:submitted.id});setInterval(()=>{},60_000);return await new Promise(()=>{});}}};const coordinator=createWorkflowTreeCoordinator({store:wrapped,...shared,workerId:'first-coordinator',definitions:[tree]});phase='coordinate';await coordinator.runPage({limit:16});throw new Error('Coordinator unexpectedly crossed the crash boundary.');}phase='recover';if(!existingRunId)throw new Error('Recovery requires the root ID.');const coordinator=createWorkflowTreeCoordinator({store:rawStore,...shared,workerId:'recovery-coordinator',definitions:[tree]});const report=await coordinator.runPage({limit:16});const repeated=await coordinator.runPage({limit:16});await notify({kind:'completed',runId:existingRunId,report,repeated});await coordinator.close();await rawStore.close();process.disconnect();}catch(error){await notify({kind:'fixture_error',phase,code:error?.code??'FIXTURE_FAILED'}).catch(()=>{});await rawStore.close().catch(()=>{});process.exitCode=1;if(process.connected)process.disconnect();}
